// Pakete Software / Betriebsführung / Gründung (Preise auf Anfrage)
import { Building2, ClipboardList, Users } from "lucide-react";
import Button from "@/components/ui/Button";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import { cn } from "@/components/ui/cn";
import { Haken } from "./teile";

const PAKETE = [
  { icon: ClipboardList, title: "Software", tag: "Selbstverwaltet", fuer: "Für Vorstände, die selbst abrechnen möchten", text: "Plattform für Vorstand, Kassa und Mitglieder: Stammdaten, EDA-Prozesse, Energiedaten, Abrechnung, Portal. Ihre Gemeinschaft arbeitet selbst, wir liefern Werkzeug und Support.", punkte: ["Mitgliederportal und Beitritt online", "Abrechnung mit Vier-Augen-Freigabe", "Export für die Steuerberatung"] },
  { icon: Users, title: "Betriebsführung", tag: "ÖkoInvest als Organisator", fuer: "Für Gemeinschaften, deren Ehrenamt entlastet werden soll", text: "Wir übernehmen als Organisator nach § 68 Abs. 2 ElWG Anmeldungen, Datenqualität, Abrechnung und Mitgliederfragen – auf Basis eines Dienstleistungs- und Auftragsverarbeitungsvertrags.", punkte: ["Kommunikation mit dem Netzbetreiber", "Lieferantenpflichten ab 100 kW (§ 69)", "Ansprechpartner für Mitglieder"] },
  { icon: Building2, title: "Gründung", tag: "Von der Idee bis zum ersten Strom", fuer: "Für Gemeinden, Vereine und Initiativen am Anfang", text: "Machbarkeit mit Simulation, Rechtsform und Statuten, Marktpartner, Vertrag mit dem Netzbetreiber, EDA-Zugang, erste Mitglieder – für Gemeinden, Vereine und Initiativen.", punkte: ["Netzgebiets- und Nahebereichs-Check", "Statuten und Verträge aus Mustern", "Startkampagne für Mitglieder"] },
];

export default function Pakete() {
  return (
    <Section data-abschnitt="pakete" tone="sand" space="lg" id="pakete" className="scroll-mt-24">
      <SectionHeading eyebrow="Pakete" title="So viel Unterstützung, wie Ihre Gemeinschaft braucht" lead="Preise auf Anfrage – wir kalkulieren je Gemeinschaft nach Größe und Leistungsumfang und legen das Angebot transparent dar." className="mb-10 md:mb-12" />
      <ul role="list" className="grid gap-5 lg:grid-cols-3">
        {PAKETE.map((p, i) => {
          const dunkel = i === 1;
          return (
            <Reveal as="li" key={p.title} className="flex lg:[--ov-delay:var(--d)]" style={{ "--d": `${i * 80}ms` }}>
              <div className={cn("ov-lift flex w-full flex-col rounded-[2rem] p-6 md:p-8", dunkel ? "ov-verlauf-nacht text-white shadow-e3 lg:-my-3 lg:py-11" : "bg-white shadow-e1 ring-1 ring-ink-200/70")}>
                <span aria-hidden="true" className={cn("order-1 flex h-12 w-12 items-center justify-center rounded-2xl", dunkel ? "bg-ov-500 text-white" : "bg-ov-50 text-ov-600")}><p.icon className="h-6 w-6" /></span>
                <h3 className="ov-h3 order-3 mt-2">{p.title}</h3>
                <p className="order-2 mt-5">
                  {dunkel
                    ? <span className="inline-flex rounded-full bg-white/10 px-2.5 py-1 text-[11.5px] font-semibold uppercase tracking-wider text-ov-300 ring-1 ring-white/15">{p.tag}</span>
                    : <span className="text-[12px] font-semibold uppercase tracking-[0.16em] text-ov-700">{p.tag}</span>}
                </p>
                <p className={cn("order-4 mt-2 text-[14px] font-medium", dunkel ? "text-white/85" : "text-ink-700")}>{p.fuer}</p>
                <p className={cn("order-5 mt-3 text-[15px] leading-relaxed lg:min-h-[7.5rem]", dunkel ? "text-white/75" : "text-ink-600")}>{p.text}</p>
                <ul className="order-6 mb-6 mt-5 space-y-2">
                  {p.punkte.map((x) => <li key={x} className={cn("ov-klein flex gap-2.5", dunkel ? "text-white/85" : "text-ink-700")}><Haken dunkel={dunkel} />{x}</li>)}
                </ul>
                <div className={cn("order-7 mt-auto border-t pt-5", dunkel ? "border-white/10" : "border-ink-100")}>
                  <p className={cn("ov-klein font-semibold", dunkel ? "text-white/75" : "text-ink-600")}>Preis nach Größe – auf Anfrage</p>
                  <Button href="#anfrage" variant={dunkel ? "primary" : "secondary"} block pfeil className="mt-3">{p.title} anfragen</Button>
                </div>
              </div>
            </Reveal>
          );
        })}
      </ul>
    </Section>
  );
}
