// Screenshots einer Seite in mehreren Breiten, sammelt Konsolenfehler.
// Aufruf: node shot.mjs <url> <ausgabeordner> [breiten, z. B. 1440,768,390] [--full | --tiles | --el=<css>]
//   --el=<css> jedes passende Element einzeln aufnehmen, z. B. --el=[data-abschnitt=hero]
//   --full   eine Ganzseiten-Aufnahme (Reveal-Inhalte werden vorher sichtbar gemacht)
//   --tiles  eine Aufnahme je Bildschirmhöhe beim echten Scrollen (wie ein Mensch sieht)
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const [url, out = "./shots", breitenArg = "1440,390", ...rest] = process.argv.slice(2);
const full = rest.includes("--full");
const tiles = rest.includes("--tiles");
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
for (const w of breitenArg.split(",").map(Number)) {
  const h = w < 700 ? 844 : 900;
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  const fehler = [];
  page.on("console", (m) => m.type() === "error" && fehler.push(m.text()));
  page.on("pageerror", (e) => fehler.push(String(e)));
  await page.goto(url, { waitUntil: "networkidle", timeout: 120000 });
  await page.waitForTimeout(600);
  // Cookie-Banner schließen, damit er keine Inhalte verdeckt
  await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(400);
  const gesamt = await page.evaluate(() => document.documentElement.scrollHeight);

  const elArg = rest.find((a) => a.startsWith("--el="));
  if (elArg) {
    // einzelne Elemente (z. B. --el=[data-abschnitt=hero]) nacheinander ins Bild scrollen und aufnehmen
    const sel = elArg.slice(5);
    const els = await page.locator(sel).all();
    if (!els.length) console.log(`  ! kein Element für ${sel}`);
    let n = 0;
    for (const el of els) {
      await el.scrollIntoViewIfNeeded();
      // langsam durch das Element scrollen, damit Reveal-Inhalte sichtbar werden
      const box = await el.boundingBox();
      if (box) for (let d = 0; d < box.height; d += 300) { await page.mouse.wheel(0, 300); await page.waitForTimeout(100); }
      await page.waitForTimeout(900);
      const name = sel.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "");
      const datei = `${out}/w${w}-${name}${els.length > 1 ? "-" + n : ""}.png`;
      n++;
      await el.screenshot({ path: datei });
      console.log(datei);
    }
  } else if (tiles) {
    let n = 0;
    for (let y = 0; y < gesamt; y += h - 80) {
      await page.evaluate((yy) => window.scrollTo(0, yy), y);
      await page.waitForTimeout(900);
      const datei = `${out}/w${w}-${String(n++).padStart(2, "0")}.png`;
      await page.screenshot({ path: datei });
      console.log(datei);
    }
  } else {
    // langsam durchscrollen, damit Reveal-Beobachter auslösen
    for (let y = 0; y < gesamt; y += 300) { await page.evaluate((yy) => window.scrollTo(0, yy), y); await page.waitForTimeout(120); }
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.waitForTimeout(800);

import { cn } from "./cn";

const TOENE = {
  white: "bg-white text-ink-900",
  sand: "bg-sand-50 text-ink-900",
  ink: "bg-ink-50 text-ink-900",
  green: "bg-ov-50 text-ink-900",
  navy: "bg-navy-950 text-white",
};

const ABSTAENDE = {
  none: "",
  sm: "py-12 md:py-16",
  md: "py-16 md:py-24",
  lg: "py-20 md:py-32",
};

/**
 * Seitenabschnitt mit einheitlichem Rhythmus.
 * tone: white | sand | ink | green | navy
 * space: none | sm | md | lg
 */
export default function Section({
  tone = "white",
  space = "md",
  id,
  className,
  containerClassName,
  bare = false,
  as: Tag = "section",
  children,
  ...rest
}) {
  return (
    <Tag
      id={id}
      className={cn("relative", TOENE[tone], ABSTAENDE[space], className)}
      {...rest}
    >
      {bare ? children : <div className={cn("ov-container relative", containerClassName)}>{children}</div>}
    </Tag>
  );
}

export function Container({ className, children }) {
  return <div className={cn("ov-container", className)}>{children}</div>;
}
import { cn } from "./cn";
import Reveal from "./Reveal";

/**
 * Kleine Überzeile über Headlines.
 * Der Punkt sitzt in einer Box mit genau einer Zeilenhöhe – einzeilig mittig zum Text,
 * bei Umbruch mittig zur ersten Zeile.
 */
export function Eyebrow({ children, dark = false, className }) {
  return (
    <p
      className={cn(
        "inline-flex items-start gap-2 text-[12.5px] font-semibold uppercase leading-[1.5] tracking-[0.16em]",
        dark ? "text-ov-300" : "text-ov-700",
        className
      )}
    >
      <span aria-hidden="true" className="flex h-[1.5em] shrink-0 items-center">
        <span className={cn("h-1.5 w-1.5 rounded-full", dark ? "bg-ov-300" : "bg-ov-500")} />
      </span>
      <span>{children}</span>
    </p>
  );
}

/**
 * Überschriftenblock eines Abschnitts.
 * as: h1 | h2 | h3 – semantische Ebene; die Optik bleibt über `size` steuerbar.
 */
export default function SectionHeading({
  eyebrow,
  title,
  lead,
  align = "left",
  dark = false,
  as: Tag = "h2",
  size = "h2",
  className,
  children,
}) {
  const zentriert = align === "center";
  return (
    <Reveal
      className={cn(
        "max-w-3xl",
        zentriert && "mx-auto text-center",
        className
      )}
    >
      {eyebrow && (
        <Eyebrow dark={dark} className={cn("mb-4", zentriert && "justify-center")}>
          {eyebrow}
        </Eyebrow>
      )}
      <Tag
        className={cn(
          size === "display" ? "ov-display" : size === "h1" ? "ov-h1" : size === "h3" ? "ov-h3" : "ov-h2",
          dark ? "text-white" : "text-ink-900"
        )}
      >
        {title}
      </Tag>
      {lead && (
        <p className={cn("ov-lead mt-5", dark ? "text-white/70" : "text-ink-600", zentriert && "mx-auto max-w-2xl")}>
          {lead}
        </p>
      )}
      {children}
    </Reveal>
  );
}
